// Add to shared/schema.ts

export const calculations = pgTable("calculations", {
  id: serial("id").primaryKey(),
  patientId: integer("patient_id").references(() => patients.id).notNull(),
  name: text("name").notNull(),
  age: integer("age").notNull(),
  sex: text("sex", { enum: ["male", "female"] }).notNull(),
  weightKg: real("weight_kg").notNull(),
  heightCm: real("height_cm").notNull(),
  bodyFatPct: real("body_fat_pct").notNull(),
  activityFactor: real("activity_factor").notNull(),
  goalType: text("goal_type", { enum: ["cut", "maintain", "bulk"] }).notNull(),
  goalAdjustmentKcal: integer("goal_adjustment_kcal").notNull(),
  proteinFactor: real("protein_factor").notNull(),
  fatGPerKg: real("fat_g_per_kg").notNull(),
  useFFMWhenHighBF: boolean("use_ffm_when_high_bf").default(true),
  proteinFactorFFM: real("protein_factor_ffm").default(2.2),
  results: jsonb("results").notNull(),
  createdAt: timestamp("created_at").defaultNow(),
});

export const ACTIVITY_FACTORS = {
  sedentary: 1.2,
  light: 1.375,
  moderate: 1.55,
  high: 1.725,
  very_high: 1.90,
} as const;

export const activityLevelEnum = z.enum(["sedentary", "light", "moderate", "high", "very_high"]);
export const goalTypeEnum = z.enum(["cut", "maintain", "bulk"]);

export const macroCalcInputSchema = z.object({
  name: z.string().min(1, "Name is required"),
  age: z.coerce.number().min(10).max(90),
  sex: z.enum(["male", "female"]),
  weightKg: z.coerce.number().min(30).max(250),
  heightCm: z.coerce.number().min(120).max(230),
  bodyFatPct: z.coerce.number().min(3).max(60),
  activityLevel: activityLevelEnum,
  activityFactor: z.coerce.number().min(1.0),
  goalType: goalTypeEnum,
  goalAdjustmentKcal: z.coerce.number(),
  proteinFactor: z.coerce.number().min(1.6).max(2.4),
  fatGPerKg: z.coerce.number().default(1.0),
  bfThresholdPct: z.coerce.number().default(20),
  useFFMWhenHighBF: z.boolean().default(true),
  proteinFactorFFM: z.coerce.number().default(2.2),
});

export type MacroCalcInput = z.infer<typeof macroCalcInputSchema>;
export const insertCalculationSchema = createInsertSchema(calculations).omit({ id: true, createdAt: true });
export type InsertCalculation = z.infer<typeof insertCalculationSchema>;
export type Calculation = typeof calculations.$inferSelect;

// Add to api object in shared/routes.ts

calculations: {
  list: {
    method: 'GET' as const,
    path: '/api/calculations',
    responses: {
      200: z.array(z.custom<typeof calculations.$inferSelect>()),
    },
  },
  create: {
    method: 'POST' as const,
    path: '/api/calculations',
    input: insertCalculationSchema,
    responses: {
      201: z.custom<typeof calculations.$inferSelect>(),
      400: errorSchemas.validation,
    },
  },
},

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { api } from "@shared/routes";
import { type InsertCalculation } from "@shared/schema";

export function useCalculations() {
  return useQuery({
    queryKey: ['calculations'],
    queryFn: async () => {
      const res = await fetch(api.calculations.list.path, { credentials: "include" });
      if (!res.ok) throw new Error("Failed to fetch calculations");
      return res.json();
    },
  });
}

export function useSaveCalculation() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: async (data: Omit<InsertCalculation, 'patientId'>) => {
      const res = await fetch(api.calculations.create.path, {
        method: 'POST',
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data),
        credentials: "include",
      });
      if (!res.ok) {
        const error = await res.json();
        throw new Error(error.message || "Failed to save calculation");
      }
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['calculations'] });
    },
  });
}

// In App.tsx Router function, add:

import Calculator from "@/pages/Calculator";

// Inside <Switch>:
<Route path="/calculator">
  <ProtectedRoute>
    <Calculator />
  </ProtectedRoute>
</Route>

// In Sidebar.tsx navItems array, add:

{
  label: "Calculator",
  href: "/calculator",
  icon: Calculator, // or Utensils from lucide-react
},
